"""Compatibility layer for Python 2 and 3."""

import abc
import os
import sys
import inspect


def _major_version_is_three():
    return 3 == sys.version_info[0]


PY3 = _major_version_is_three()


if 'ABC' in dir(abc):
    ABC = abc.ABC
else:
    class ABC(object):
        """Helper class that provides a standard way to create an ABC using
        inheritance.
        """
        __metaclass__ = abc.ABCMeta
        __slots__ = ()


if getattr(os, 'PathLike', None) is not None:
    PathLike = os.PathLike
else:
    class PathLike(ABC):
        """Abstract base class for implementing the file system path protocol."""

        @abc.abstractmethod
        def __fspath__(self):
            """Return the file system path representation of the object."""
            raise NotImplementedError

        @classmethod
        def __subclasshook__(cls, subclass):
            if hasattr(subclass, '__fspath__'):
                return True
            # Make a concession for older `pathlib` versions:g
            return (hasattr(subclass, 'open') and
                    subclass.__name__.lower().find('path') != -1)


try:
    iscoroutinefunction = inspect.iscoroutinefunction
except AttributeError:
    def iscoroutinefunction(func):  # Lolz
        return False


if PY3:
    string_types = (str,)
    text_type = str
else:
    string_types = (basestring,)  # noqa: F821
    text_type = unicode  # noqa: F821
